    A simple implementation of a linked list with consistent naming conventions.

    Attributes:
        _head (Node): The head node of the linked list.
    """

    class _Node:
        """Private node class to represent a node in the linked list."""

        def __init__(self, data: any) -> None:
            self._data: any = data
            self._next: '_Node' = None

    def __init__(self) -> None:
        self._head: '_Node' = None

    def append(self, data: any) -> None:
        """Add a new node with the given data to the end of the list."""
        new_node = self._Node(data)
        if self._head is None:
            self._head = new_node
        else:
            current = self._head
            while current._next is not None:
                current = current._next
            current._next = new_node

    def get_length(self) -> int:
        """Return the number of nodes in the linked list."""
        count: int = 0
        current: '_Node' = self._head
        while current is not None:
            count += 1
            current = current._next
        return count

    def find(self, data: any) -> bool:
        """Check if the given data exists in the linked list."""
        current: '_Node' = self._head
        while current is not None:
            if current._data == data:
                return True
            current = current._next
        return False

    def remove(self, data: any) -> bool:
        """Remove the first occurrence of the given data from the list."""
        if self._head is None:
            return False

        if self._head._data == data:
            self._head = self._head._next
            return True

        current: '_Node' = self._head
        while current._next is not None:
            if current._next._data == data:
                current._next = current._next._next
                return True
            current = current._next
        return False

    def __str__(self) -> str:
        """Return a string representation of the linked list."""
        result: list[str] = []
        current: '_Node' = self._head
        while current is not None:
            result.append(str(current._data))
            current = current._next
        return " -> ".join(result) if result else "Empty List"
