    if len(arr) <= 1:
        return arr

    mid = len(arr) // 2
    left = b_merge_sort(arr[:mid])
    right = b_merge_sort(arr[mid:])

    return b_merge_arrays(left, right)


def b_merge_arrays(left, right):
    result = []
    i = j = 0

    while i < len(left) and j < len(right):
        if left[i] <= right[j]:
            result.append(left[i])
            i += 1
        else:
            result.append(right[j])
            j += 1

    result.extend(left[i:])
    result.extend(right[j:])

    return result
