            assert e_x.dim() == 4, "Input must be a 4D tensor (batch, channels, height, width)"
            assert e_x.size(1) == 1, "Input must have 1 channel"
            assert e_x.size(2) * e_x.size(3) <= self.vr_input_size, "Input size exceeds defined limit"

            return self.chx_model(e_x)
        except Exception as e:
            raise RuntimeError(f"Forward pass failed: {str(e)}")

    @count_calls
