    @validate
    @rename_kwargs
    @retry
    def fn_chx_loss(self, e_output: torch.Tensor, e_target: torch.Tensor) -> torch.Tensor:
        """
        Compute the binary cross-entropy loss between model output and target.

        Args:
            e_output (torch.Tensor): Model output logits of shape (batch_size, 2)
            e_target (torch.Tensor): Target labels of shape (batch_size,)

