            assert e_target.dim() == 1, "Target must be 1D"
            assert e_output.size(0) == e_target.size(0), "Batch sizes must match"

            return nn.BCEWithLogitsLoss()(e_output, e_target.float())
        except Exception as e:
            raise RuntimeError(f"Loss computation failed: {str(e)}")

