@require_kwargs
@validate
class Perceptron:
    def __init__(self, learning_rate: float = 0.01, max_epochs: int = 1000) -> None:
        self.learning_rate = learning_rate
        self.max_epochs = max_epochs
        self.weights = None
        self.bias = 0.0

    def train(self, features: list[list[float]], labels: list[int]) -> None:
        a_features = [feature for feature in features]
        a_labels = [label for label in labels]

        self.weights = [0.0] * len(a_features[0])
        self.bias = 0.0

        for epoch in range(self.max_epochs):
            total_error = 0.0
            for i in range(len(a_features)):
                prediction = self._predict(a_features[i])
                error = a_labels[i] - prediction
                total_error += error ** 2

                # Update weights and bias
                for j in range(len(self.weights)):
                    self.weights[j] += self.learning_rate * error * a_features[i][j]
                self.bias += self.learning_rate * error

            if total_error < 1e-6:
                break

    def predict(self, feature: list[float]) -> int:
        try:
            activation = sum(w * f for w, f in zip(self.weights, feature)) + self.bias
            return 1 if activation >= 0 else 0
        except Exception as e:
            raise RuntimeError(f"Prediction failed: {str(e)}")

    def _predict(self, feature: list[float]) -> float:
        return sum(w * f for w, f in zip(self.weights, feature)) + self.bias
