        self.head = new_node
        self._size += 1

    def append(self, value):
        new_node = Node(value)
        if not self.head:
            self.head = new_node
        else:
            current = self.head
            while current.next:
                current = current.next
            current.next = new_node
        self._size += 1

    def delete(self, value):
        try:
            if not self.head:
                return False
            if self.head.value == value:
                self.head = self.head.next
                self._size -= 1
                return True
            current = self.head
            while current.next and current.next.value != value:
                current = current.next
            if current.next:
                current.next = current.next.next
                self._size -= 1
                return True
            return False
        except Exception as e:
            print(f"Error during deletion: {e}")
            return False

    def search(self, value):
        try:
            current = self.head
            while current:
                if current.value == value:
                    return True
                current = current.next
            return False
        except Exception as e:
            print(f"Error during search: {e}")
            return False

    def get_size(self):
        return self._size

    def is_empty(self):
        return self.head is None

    def to_list(self):
        result = []
        current = self.head
        while current:
            result.append(current.value)
            current = current.next
        return result

    def reverse(self):
        try:
            prev = None
            current = self.head
            while current:
                next_node = current.next
                current.next = prev
                prev = current
                current = next_node
            self.head = prev
        except Exception as e:
            print(f"Error during reverse: {e}")

    def get_nth(self, n):
        try:
            if n < 0 or n >= self._size:
                return None
            current = self.head
            for _ in range(n):
                current = current.next
            return current.value
        except Exception as e:
            print(f"Error during get_nth: {e}")
            return None

    def remove_duplicates(self):
        try:
            if not self.head or not self.head.next:
                return
            seen = set()
            current = self.head
            while current:
                if current.value in seen:
                    # Remove the node
                    if current == self.head:
                        self.head = current.next
                    else:
                        prev = self.head
                        while prev.next != current:
                            prev = prev.next
                        prev.next = current.next
                    self._size -= 1
                else:
                    seen.add(current.value)
                current = current.next
        except Exception as e:
            print(f"Error during remove_duplicates: {e}")


